export type TerrainType = 'plains' | 'forest' | 'water' | 'stone'
export type UnitKind = 'pc' | 'npc'
export type Direction = 'up' | 'down' | 'left' | 'right'
export type PcType = 'melee' | 'ranger' | 'magic-user' | 'rogue'
export type NpcType = 'short-range' | 'long-range'

// Data-defined description of a unit archetype's behavior. The engine derives a
// unit's move range, max HP, attack damage, and attack footprint from this table
// (see `unitDefs.ts`) rather than from per-archetype code branches. The subset
// here is exactly what today's six archetypes exercise; framework fields not yet
// used (traversal, layers, status, …) are intentionally omitted.
export interface UnitDef {
  maxHp: number
  movement: { range: number }
  attack: {
    damage: number
    targeting: { mode: 'direction'; arc: 'cardinal'; minRange: number; maxRange: number }
    propagation: { shape: 'single' | 'line' | 'plus'; penetration: 'none' | 'stop_at_first' }
  }
}

export interface Cell {
  terrain: TerrainType
  hasStructure: boolean
  structureHp?: number
  structureKind?: 'power-center' | 'tower'
}

export interface PcPlan {
  moveTarget?: { col: number; row: number }
  movePath?: Array<{ col: number; row: number }>
  attackDir?: Direction
}

export interface Unit {
  id: string
  kind: UnitKind
  col: number
  row: number
  unitType: PcType | NpcType
  hp: number
}

export type PlanningPhase = 'none' | 'selecting-move' | 'selecting-attack'
export type TurnPhase = 'placement' | 'player' | 'npc-move' | 'npc-attack'

// A reversible record of a committed PC move. Captures everything a move mutates
// so popping it fully restores the prior state: the moving unit's id, its origin
// and destination, and the path travelled (used to animate the reversal).
export interface UndoRecord {
  unitId: string
  fromCol: number
  fromRow: number
  toCol: number
  toRow: number
  path: Array<{ col: number; row: number }>
}

export interface PathFilter {
  ignoreStructures?: boolean
  ignorePcs?: boolean
  ignoreNpcs?: boolean
}

export interface GameState {
  cells: Cell[][]
  units: Unit[]
  spawners: { col: number; row: number }[]
  phase: TurnPhase
  planningPhase: PlanningPhase
  selectedUnitId: string | null
  plans: Record<string, PcPlan>
  planOrder: string[]
  // Telegraphed NPC attacks for the current round, computed during `npc-move`
  // from each NPC's post-move position and resolved on the player's confirm.
  // NPCs that only moved/stayed/exited have no entry.
  npcPlans: NpcAttackPlan[]
  // Stack of reversible PC move records for the current player phase. Pushed on
  // each immediate move, cleared when any PC attacks or the round ends.
  undoStack: UndoRecord[]
  // Per-unit movement consumed this player turn (tiles stepped). A PC may move
  // multiple times but only up to `moveRange` tiles total; remaining = range − this.
  movedThisTurn: Record<string, number>
  // PCs that have attacked this player turn. An attack is committal: once a PC
  // attacks it can neither move nor attack again until the round ends.
  attackedThisTurn: string[]
}

export type PcAction =
  | { kind: 'move-attack'; unitId: string; fromCol: number; fromRow: number; toCol: number; toRow: number; path: Array<{ col: number; row: number }>; attackDir: Direction }
  | { kind: 'move'; unitId: string; fromCol: number; fromRow: number; toCol: number; toRow: number; path: Array<{ col: number; row: number }> }
  | { kind: 'attack'; unitId: string; col: number; row: number; attackDir: Direction }
  | { kind: 'stay'; unitId: string }

// Per-NPC actions executed immediately during the `npc-move` phase. Movement and
// attack are no longer bundled: an NPC that closes to contact emits a `move` here
// plus a separate `NpcAttackPlan` telegraph resolved later.
export type NpcAction =
  | { kind: 'move'; unitId: string; fromCol: number; fromRow: number; toCol: number; toRow: number; path: Array<{ col: number; row: number }> }
  | { kind: 'attack'; unitId: string; targetCol: number; targetRow: number }
  | { kind: 'exit'; unitId: string; fromCol: number; fromRow: number }
  | { kind: 'stay'; unitId: string }

// A telegraphed NPC attack stored after the NPC moves and resolved when the
// player confirms end-of-turn. Target is the cell as seen from the NPC's
// post-move position.
export type NpcAttackPlan = { kind: 'attack'; unitId: string; targetCol: number; targetRow: number }

import type { Cell, Unit } from './types'
import { gridCols, gridRows } from './contentStore'

export function damageStructure(cells: Cell[][], col: number, row: number): Cell[][] {
  const hp = cells[row][col].structureHp ?? 0
  if (hp <= 0) return cells
  const newHp = hp - 1
  return cells.map((r, ri) =>
    ri !== row ? r : r.map((c, ci) =>
      ci !== col ? c : { ...c, structureHp: newHp, hasStructure: newHp > 0 }
    )
  )
}

export function occupiedKey(units: Unit[]): Set<string> {
  return new Set(units.map((u) => `${u.col},${u.row}`))
}

export function structureKeys(cells: Cell[][]): Set<string> {
  const keys = new Set<string>()
  const rows = gridRows()
  const cols = gridCols()
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (cells[r][c].hasStructure) keys.add(`${c},${r}`)
    }
  }
  return keys
}

function powerCenterCount(cells: Cell[][]): number {
  let n = 0
  const rows = gridRows()
  const cols = gridCols()
  for (let r = 0; r < rows; r++)
    for (let c = 0; c < cols; c++)
      if (cells[r][c].hasStructure && cells[r][c].structureKind === 'power-center') n++
  return n
}

export function isTowerImmune(cells: Cell[][]): boolean {
  return powerCenterCount(cells) >= 2
}

import type { GameState, Direction, PcAction, PcPlan, Unit, UndoRecord } from './types'
import { playerSpawnZone } from './contentStore'
import { inBounds, astar } from './pathfinding'
import { occupiedKey, structureKeys, damageStructure } from './turn'
import { getDef, getMoveRange } from './defStore'
import { attackFootprint } from './attackFootprint'

const DIR_OFFSETS: Record<Direction, [number, number]> = {
  up: [0, -1],
  down: [0, 1],
  left: [-1, 0],
  right: [1, 0],
}

// ─── Unit stats ───────────────────────────────────────────────────────────────

// Delegates to the loaded in-memory def store so edits take effect for every
// caller (validMoveDests, remainingMove, NPC planning, the popup) without any
// signature changes.
export function moveRange(unit: Unit): number {
  return getMoveRange(unit.unitType)
}

export function attackDamage(unit: Unit): number {
  return getDef(unit.unitType).attack.damage
}

// Display name for a unit in the info popup. NPCs surface their unit type
// (e.g. `short-range`) as their name.
export function unitDisplayName(unit: Unit): string {
  return unit.unitType
}

// ─── Planning helpers ────────────────────────────────────────────────────────

export function selectUnit(state: GameState, id: string): GameState {
  // PCs land directly in move-selection so walk tiles show on select; NPCs — and
  // PCs that have already attacked (locked for the turn) — are info-only (no
  // planning phase, so no walk/attack overlays or Attack toggle are drawn).
  const unit = state.units.find((u) => u.id === id)
  const planningPhase = unit?.kind === 'pc' && !hasAttacked(state, id) ? 'selecting-move' : 'none'
  return { ...state, selectedUnitId: id, planningPhase }
}

export function cancelSelection(state: GameState): GameState {
  return { ...state, selectedUnitId: null, planningPhase: 'none' }
}

// ─── Turn-0 placement ──────────────────────────────────────────────────────────

// Select a PC during the placement phase: it becomes selected (opening the info
// dialog) but enters no planning phase, so no walk/attack overlays are drawn and
// the dialog stays a pure info view while the player repositions units.
export function selectForPlacement(state: GameState, id: string): GameState {
  return { ...state, selectedUnitId: id, planningPhase: 'none' }
}

// Relocate a unit to (col,row) during placement. The move only takes effect when
// the target is a valid spawn-zone tile, holds no structure, and is unoccupied;
// any other target leaves the state unchanged so the player can keep trying.
export function placeUnit(state: GameState, id: string, col: number, row: number): GameState {
  const unit = state.units.find((u) => u.id === id)
  if (!unit || unit.kind !== 'pc') return state
  const key = `${col},${row}`
  if (!playerSpawnZone().has(key)) return state
  if (state.cells[row]?.[col]?.hasStructure) return state
  if (occupiedKey(state.units).has(key)) return state
  const units = state.units.map((u) => (u.id === id ? { ...u, col, row } : u))
  return { ...state, units }
}

export function beginPlanMove(state: GameState): GameState {
  return { ...state, planningPhase: 'selecting-move' }
}

export function beginPlanAttack(state: GameState): GameState {
  return { ...state, planningPhase: 'selecting-attack' }
}

export function setPlanMove(state: GameState, unitId: string, col: number, row: number, path: Array<{ col: number; row: number }>): GameState {
  const existing = state.plans[unitId] ?? {}
  const newPlanOrder = [...state.planOrder.filter((id) => id !== unitId), unitId]
  return {
    ...state,
    plans: { ...state.plans, [unitId]: { ...existing, moveTarget: { col, row }, movePath: path } },
    planOrder: newPlanOrder,
    planningPhase: 'none',
  }
}

export function setPlanAttack(state: GameState, unitId: string, dir: Direction): GameState {
  const existing = state.plans[unitId] ?? {}
  const newPlanOrder = [...state.planOrder.filter((id) => id !== unitId), unitId]
  return {
    ...state,
    plans: { ...state.plans, [unitId]: { ...existing, attackDir: dir } },
    planOrder: newPlanOrder,
    planningPhase: 'none',
  }
}

export function clearPlan(state: GameState, unitId: string): GameState {
  const plans = { ...state.plans }
  delete plans[unitId]
  return {
    ...state,
    plans,
    planOrder: state.planOrder.filter((id) => id !== unitId),
  }
}

export function clearPlanMove(state: GameState, unitId: string): GameState {
  const existing = state.plans[unitId]
  if (!existing?.moveTarget) return { ...state, planningPhase: 'none' }
  const plans = { ...state.plans }
  if (!existing.attackDir) {
    delete plans[unitId]
    return { ...state, plans, planOrder: state.planOrder.filter((id) => id !== unitId), planningPhase: 'none' }
  }
  plans[unitId] = { attackDir: existing.attackDir }
  return { ...state, plans, planningPhase: 'none' }
}

export function clearPlanAttack(state: GameState, unitId: string): GameState {
  const existing = state.plans[unitId]
  if (!existing?.attackDir) return { ...state, planningPhase: 'none' }
  const plans = { ...state.plans }
  if (!existing.moveTarget) {
    delete plans[unitId]
    return { ...state, plans, planOrder: state.planOrder.filter((id) => id !== unitId), planningPhase: 'none' }
  }
  plans[unitId] = { moveTarget: existing.moveTarget }
  return { ...state, plans, planningPhase: 'none' }
}

// ─── Undo stack & immediate moves ──────────────────────────────────────────────

// Tiles a unit may still step this turn: its archetype range minus what it has
// already moved. A PC that has attacked is locked (no remaining movement).
export function remainingMove(state: GameState, unit: Unit): number {
  if (hasAttacked(state, unit.id)) return 0
  return moveRange(unit) - (state.movedThisTurn[unit.id] ?? 0)
}

// Whether a PC has attacked this turn. Attacks are committal: an attacked PC can
// neither move nor attack again until the round ends.
export function hasAttacked(state: GameState, unitId: string): boolean {
  return state.attackedThisTurn.includes(unitId)
}

export function pushUndo(state: GameState, record: UndoRecord): GameState {
  return { ...state, undoStack: [...state.undoStack, record] }
}

export function clearUndo(state: GameState): GameState {
  if (state.undoStack.length === 0) return state
  return { ...state, undoStack: [] }
}

// Commit a PC move immediately: update the unit's position, charge the tiles
// moved against its turn budget, and push a reversible record onto the undo
// stack. Mutates only `units`, `undoStack`, and `movedThisTurn` so that
// undoLastMove(applyMove(s, …)) round-trips back to `s`.
export function applyMove(
  state: GameState,
  unitId: string,
  toCol: number, toRow: number,
  path: Array<{ col: number; row: number }>,
): GameState {
  const unit = state.units.find((u) => u.id === unitId)
  if (!unit) return state
  const record: UndoRecord = { unitId, fromCol: unit.col, fromRow: unit.row, toCol, toRow, path }
  const units = state.units.map((u) => (u.id === unitId ? { ...u, col: toCol, row: toRow } : u))
  const movedThisTurn = {
    ...state.movedThisTurn,
    [unitId]: (state.movedThisTurn[unitId] ?? 0) + path.length,
  }
  return pushUndo({ ...state, units, movedThisTurn }, record)
}

// Pop the most recent move, restore the affected unit to its origin, and refund
// the tiles it spent back into its turn budget. A no-op on an empty stack.
export function undoLastMove(state: GameState): GameState {
  if (state.undoStack.length === 0) return state
  const record = state.undoStack[state.undoStack.length - 1]
  const units = state.units.map((u) =>
    u.id === record.unitId ? { ...u, col: record.fromCol, row: record.fromRow } : u,
  )
  const movedThisTurn = { ...state.movedThisTurn }
  const refunded = (movedThisTurn[record.unitId] ?? 0) - record.path.length
  if (refunded > 0) movedThisTurn[record.unitId] = refunded
  else delete movedThisTurn[record.unitId]
  return { ...state, units, movedThisTurn, undoStack: state.undoStack.slice(0, -1) }
}

// ─── Queries ─────────────────────────────────────────────────────────────────

export function validMoveDests(state: GameState, unitId: string): { col: number; row: number }[] {
  const unit = state.units.find((u) => u.id === unitId)
  if (!unit) return []
  // Only the movement still left this turn is reachable (zero once a PC has used
  // its full range or has attacked), so repeated moves can't exceed the range.
  const limit = remainingMove(state, unit)
  if (limit <= 0) return []
  const occupied = occupiedKey(state.units)
  const structures = structureKeys(state.cells)

  const reachable = new Set<string>()
  const visited = new Set<string>([`${unit.col},${unit.row}`])
  const queue: Array<{ col: number; row: number; steps: number }> = [
    { col: unit.col, row: unit.row, steps: 0 },
  ]

  while (queue.length > 0) {
    const { col, row, steps } = queue.shift()!
    if (steps >= limit) continue
    for (const [dc, dr] of Object.values(DIR_OFFSETS) as [number, number][]) {
      const nc = col + dc
      const nr = row + dr
      const key = `${nc},${nr}`
      if (!inBounds(nc, nr) || structures.has(key) || occupied.has(key)) continue
      if (!visited.has(key)) {
        visited.add(key)
        reachable.add(key)
        queue.push({ col: nc, row: nr, steps: steps + 1 })
      }
    }
  }

  return Array.from(reachable).map((key) => {
    const [c, r] = key.split(',').map(Number)
    return { col: c, row: r }
  })
}

export function computeMovePath(
  state: GameState,
  unitId: string,
  fromCol: number, fromRow: number,
  toCol: number, toRow: number,
): Array<{ col: number; row: number }> {
  return astar(state.cells, state.units, { col: fromCol, row: fromRow }, { col: toCol, row: toRow }, {}, unitId) ?? []
}

export function attackSquares(state: GameState, unitId: string): { col: number; row: number }[] {
  const unit = state.units.find((u) => u.id === unitId)
  if (!unit) return []
  const plan = state.plans[unitId]
  const attackDir = plan?.attackDir
  if (!attackDir) return []

  const baseCol = plan?.moveTarget?.col ?? unit.col
  const baseRow = plan?.moveTarget?.row ?? unit.row

  return attackFootprint(getDef(unit.unitType), { col: baseCol, row: baseRow }, attackDir)
}

// ─── Turn resolution ──────────────────────────────────────────────────────────

export function resolvePcAction(state: GameState, action: PcAction): GameState {
  if (action.kind === 'stay') return state

  let units = [...state.units]
  let cells = state.cells
  const structures = structureKeys(cells)

  const resolveAttack = (attacker: Unit, attackDir: Direction) => {
    const def = getDef(attacker.unitType)
    const damage = attackDamage(attacker)
    const { penetration } = def.attack.propagation
    const tiles = attackFootprint(def, { col: attacker.col, row: attacker.row }, attackDir)

    const applyDamageTo = (tc: number, tr: number, dmg: number) => {
      const target = units.find((u) => u.kind === 'npc' && u.col === tc && u.row === tr)
      if (target) {
        units = units.map((u) => u.id === target.id ? { ...u, hp: u.hp - dmg } : u)
      } else if (cells[tr]?.[tc]?.hasStructure) {
        cells = damageStructure(cells, tc, tr)
      }
    }

    // `stop_at_first` (ranger line): damage the nearest occupied/structure tile
    // and stop. `none` (melee single, magic-user plus): damage every footprint
    // tile. Footprint tiles are board-clipped and ordered by distance already.
    for (const { col: tc, row: tr } of tiles) {
      if (penetration === 'stop_at_first') {
        const hit = units.some((u) => u.kind === 'npc' && u.col === tc && u.row === tr) || cells[tr]?.[tc]?.hasStructure
        if (hit) { applyDamageTo(tc, tr, damage); break }
      } else {
        applyDamageTo(tc, tr, damage)
      }
    }

    units = units.filter((u) => u.hp > 0)
  }

  if (action.kind === 'move' || action.kind === 'move-attack') {
    const otherOccupied = occupiedKey(units.filter((u) => u.id !== action.unitId))
    const destKey = `${action.toCol},${action.toRow}`
    const blocked = otherOccupied.has(destKey) || structures.has(destKey)

    if (!blocked) {
      units = units.map((u) => (u.id === action.unitId ? { ...u, col: action.toCol, row: action.toRow } : u))
    }

    if (action.kind === 'move-attack') {
      const mover = units.find((u) => u.id === action.unitId)!
      resolveAttack(mover, action.attackDir)
    }
  } else if (action.kind === 'attack') {
    const unit = units.find((u) => u.id === action.unitId)!
    resolveAttack(unit, action.attackDir)
  }

  // Attacks are committal: resolving one clears the undo stack (so prior moves can
  // no longer be undone) and locks the attacker for the rest of the turn — it can
  // neither move nor attack again. endRound clears both.
  const attacked = action.kind === 'attack' || action.kind === 'move-attack'
  const undoStack = attacked ? [] : state.undoStack
  const attackedThisTurn =
    attacked && !state.attackedThisTurn.includes(action.unitId)
      ? [...state.attackedThisTurn, action.unitId]
      : state.attackedThisTurn
  return { ...state, units, cells, undoStack, attackedThisTurn }
}

import { describe, it, expect } from 'vitest'
import { attackFootprint } from './attackFootprint'
import { unitDefs } from './unitDefs'
import { gridCols, gridRows } from './contentStore'

// Compare two tile lists as sets (order-independent) via "col,row" keys.
const keys = (tiles: { col: number; row: number }[]) => tiles.map((t) => `${t.col},${t.row}`).sort()

describe('attackFootprint', () => {
  describe('single (melee/rogue)', () => {
    it('covers the one adjacent tile in the aimed direction', () => {
      const fp = attackFootprint(unitDefs.melee, { col: 5, row: 5 }, 'right')
      expect(keys(fp)).toEqual(['6,5'])
    })

    it('is empty when the adjacent tile is off the board', () => {
      const fp = attackFootprint(unitDefs.melee, { col: gridCols() - 1, row: 5 }, 'right')
      expect(fp).toEqual([])
    })
  })

  describe('line (ranger)', () => {
    it('covers distance 2 to the board edge, ordered by increasing distance', () => {
      const fp = attackFootprint(unitDefs.ranger, { col: 5, row: 5 }, 'right')
      // origin col 5, right → cols 7..15 at row 5
      expect(fp).toEqual([
        { col: 7, row: 5 }, { col: 8, row: 5 }, { col: 9, row: 5 }, { col: 10, row: 5 },
        { col: 11, row: 5 }, { col: 12, row: 5 }, { col: 13, row: 5 }, { col: 14, row: 5 },
        { col: 15, row: 5 },
      ])
    })

    it('clips at the top edge when aimed up', () => {
      const fp = attackFootprint(unitDefs.ranger, { col: 5, row: 5 }, 'up')
      // origin row 5, up → rows 3,2,1,0 at col 5 (distance 2 to edge)
      expect(fp).toEqual([
        { col: 5, row: 3 }, { col: 5, row: 2 }, { col: 5, row: 1 }, { col: 5, row: 0 },
      ])
    })

    it('is empty when distance 2 is already off the board', () => {
      const fp = attackFootprint(unitDefs.ranger, { col: gridCols() - 1, row: 5 }, 'right')
      expect(fp).toEqual([])
    })
  })

  describe('plus (magic-user)', () => {
    it('covers the center at distance 2 plus its 4 cardinal neighbors', () => {
      const fp = attackFootprint(unitDefs['magic-user'], { col: 5, row: 5 }, 'right')
      // center (7,5) + (6,5),(8,5),(7,4),(7,6)
      expect(keys(fp)).toEqual(keys([
        { col: 7, row: 5 }, { col: 6, row: 5 }, { col: 8, row: 5 }, { col: 7, row: 4 }, { col: 7, row: 6 },
      ]))
    })

    it('clips a neighbor that falls off the board edge', () => {
      const fp = attackFootprint(unitDefs['magic-user'], { col: 0, row: 5 }, 'up')
      // center (0,3); neighbors (-1,3) off-board, (1,3),(0,2),(0,4) on-board
      expect(keys(fp)).toEqual(keys([
        { col: 0, row: 3 }, { col: 1, row: 3 }, { col: 0, row: 2 }, { col: 0, row: 4 },
      ]))
    })

    it('keeps only the on-board tiles when the center is off the board', () => {
      const fp = attackFootprint(unitDefs['magic-user'], { col: 5, row: 1 }, 'up')
      // center (5,-1) off-board; only neighbor (5,0) is on-board
      expect(keys(fp)).toEqual(['5,0'])
    })
  })

  it('stays within the board for every shape and direction', () => {
    for (const def of Object.values(unitDefs)) {
      for (const dir of ['up', 'down', 'left', 'right'] as const) {
        const fp = attackFootprint(def, { col: 8, row: 4 }, dir)
        for (const t of fp) {
          expect(t.col).toBeGreaterThanOrEqual(0)
          expect(t.col).toBeLessThan(gridCols())
          expect(t.row).toBeGreaterThanOrEqual(0)
          expect(t.row).toBeLessThan(gridRows())
        }
      }
    }
  })
})

import { describe, it, expect } from 'vitest'
import { initialState, computeNpcTurns } from './npc'
import type { GameState, NpcAction, NpcAttackPlan, NpcType } from './types'

function npcIds(state: GameState): string[] {
  return state.units.filter((u) => u.kind === 'npc').map((u) => u.id)
}

// A player-phase state holding a single NPC over the seed board (with its
// structures/power-centers intact), so each archetype's move/attack split can be
// asserted without interference from the other enemies.
function singleNpc(unitType: NpcType, col: number, row: number): GameState {
  const s = initialState()
  return {
    ...s,
    phase: 'player',
    units: [{ id: 'npc-0', kind: 'npc', col, row, unitType, hp: 3 }],
    npcPlans: [],
  }
}

// Where each NPC ends the move phase: a move's destination, its current cell when
// it stays, or dropped when it exits.
function postMovePositions(state: GameState, moves: NpcAction[]): Map<string, { col: number; row: number }> {
  const pos = new Map<string, { col: number; row: number }>()
  for (const u of state.units) if (u.kind === 'npc') pos.set(u.id, { col: u.col, row: u.row })
  for (const m of moves) {
    if (m.kind === 'move') pos.set(m.unitId, { col: m.toCol, row: m.toRow })
    else if (m.kind === 'exit') pos.delete(m.unitId)
  }
  return pos
}

describe('computeNpcTurns — move/attack split', () => {
  it('returns movement actions and attack telegraphs as separate lists', () => {
    const s = initialState()
    const { moves, attackPlans } = computeNpcTurns(s)
    const ids = new Set(npcIds(s))
    // Movement actions are only move/exit/stay — the bundled `move-attack` variant
    // is gone, and attacks never appear here.
    for (const m of moves) {
      expect(ids.has(m.unitId)).toBe(true)
      expect(['move', 'exit', 'stay']).toContain(m.kind)
    }
    // Every telegraph is an attack belonging to an NPC.
    for (const p of attackPlans) {
      expect(p.kind).toBe('attack')
      expect(ids.has(p.unitId)).toBe(true)
    }
  })

  it('emits exactly one movement action per living NPC', () => {
    const s = initialState()
    const { moves } = computeNpcTurns(s)
    // No seed NPC starts on the exit row, so each produces one move/stay entry.
    expect(moves.map((m) => m.unitId).sort()).toEqual(npcIds(s).sort())
  })

  it('telegraphs every attack from the NPC post-move position, cardinally aligned', () => {
    const s = initialState()
    const { moves, attackPlans } = computeNpcTurns(s)
    const pos = postMovePositions(s, moves)
    for (const p of attackPlans) {
      const from = pos.get(p.unitId)!
      const sameCol = from.col === p.targetCol
      const sameRow = from.row === p.targetRow
      expect(sameCol || sameRow).toBe(true)
      expect(Math.abs(from.col - p.targetCol) + Math.abs(from.row - p.targetRow)).toBeGreaterThanOrEqual(1)
    }
  })
})

describe('computeNpcTurns — short-range archetype', () => {
  it('stays and telegraphs when already adjacent to a power-center', () => {
    // npc-0 directly above the (5,4) power-center: a distance-1 stationary attack.
    const s = singleNpc('short-range', 5, 3)
    const { moves, attackPlans } = computeNpcTurns(s)
    expect(moves).toEqual([{ kind: 'stay', unitId: 'npc-0' }])
    expect(attackPlans).toEqual([{ kind: 'attack', unitId: 'npc-0', targetCol: 5, targetRow: 4 }])
  })

  it('moves into contact and telegraphs the attack from its destination', () => {
    // npc-0 three tiles above (5,4), out of attack range (max 2): it closes to the
    // adjacent cell (5,3) and telegraphs the structure attack from there.
    const s = singleNpc('short-range', 5, 1)
    const { moves, attackPlans } = computeNpcTurns(s)
    expect(moves.length).toBe(1)
    const move = moves[0]
    expect(move.kind).toBe('move')
    if (move.kind === 'move') {
      expect({ col: move.toCol, row: move.toRow }).toEqual({ col: 5, row: 3 })
    }
    expect(attackPlans).toEqual([{ kind: 'attack', unitId: 'npc-0', targetCol: 5, targetRow: 4 }])
  })
})

describe('computeNpcTurns — long-range archetype', () => {
  it('stays and telegraphs a ranged attack on a target at distance 2', () => {
    // npc-0 two tiles above the (5,4) power-center, within long-range (min 2).
    const s = singleNpc('long-range', 5, 2)
    const { moves, attackPlans } = computeNpcTurns(s)
    expect(moves).toEqual([{ kind: 'stay', unitId: 'npc-0' }])
    expect(attackPlans).toEqual([{ kind: 'attack', unitId: 'npc-0', targetCol: 5, targetRow: 4 }])
  })
})

describe('computeNpcTurns — attack-only re-plan (live def edit)', () => {
  // Two short-range NPCs each adjacent to a power-center; both have a telegraph.
  function twoAdjacent(npcPlans: NpcAttackPlan[]): GameState {
    const s = initialState()
    return {
      ...s,
      phase: 'player',
      units: [
        { id: 'npc-0', kind: 'npc', col: 5, row: 3, unitType: 'short-range', hp: 3 },
        { id: 'npc-1', kind: 'npc', col: 11, row: 3, unitType: 'short-range', hp: 3 },
      ],
      npcPlans,
    }
  }

  it('returns no movement and reuses every prior telegraph for an empty set', () => {
    const planA: NpcAttackPlan = { kind: 'attack', unitId: 'npc-0', targetCol: 5, targetRow: 4 }
    const planB: NpcAttackPlan = { kind: 'attack', unitId: 'npc-1', targetCol: 11, targetRow: 4 }
    const s = twoAdjacent([planA, planB])
    const { moves, attackPlans } = computeNpcTurns(s, new Set<string>())
    expect(moves).toEqual([])
    expect(attackPlans).toEqual([planA, planB])
    // Reused verbatim (same object identity), not recomputed.
    expect(attackPlans[0]).toBe(planA)
    expect(attackPlans[1]).toBe(planB)
  })

  it('recomputes only the replanned NPC and reuses the rest, with no movement', () => {
    // npc-0's prior telegraph is stale (wrong target); npc-1's is correct.
    const stale: NpcAttackPlan = { kind: 'attack', unitId: 'npc-0', targetCol: 0, targetRow: 0 }
    const planB: NpcAttackPlan = { kind: 'attack', unitId: 'npc-1', targetCol: 11, targetRow: 4 }
    const s = twoAdjacent([stale, planB])
    const { moves, attackPlans } = computeNpcTurns(s, new Set(['npc-0']))
    expect(moves).toEqual([])
    // npc-0 recomputed from its current (immutable) position; npc-1 reused.
    expect(attackPlans).toEqual([
      { kind: 'attack', unitId: 'npc-0', targetCol: 5, targetRow: 4 },
      planB,
    ])
    expect(attackPlans[1]).toBe(planB)
  })
})

import type { Cell } from './types'
import type { ContentMap, ContentEncounter, ContentTree } from './contentTypes'
import { BUNDLED_MAP } from './bundledMap'
import { fetchDefaultContent, fetchMapWithEncounters } from '../../api'

// The single in-memory source of truth the engine reads board content from —
// the board grid, its dimensions, tile objects, and the enemy/player spawn
// zones. It mirrors `defStore` (which holds unit stats): at game start
// `loadFromServer()` populates it from the persisted default Map; if that fetch
// fails it keeps the bundled `BUNDLED_MAP` so the game stays playable offline /
// on error. The engine (`npc.ts`, `pc.ts`, `pathfinding.ts`, `turn.ts`,
// `DungeonTacticsScene.ts`) reads board content only through the getters here —
// the bundled tree is the fallback seed.
//
// There is no polling / mid-session re-fetch: `loadFromServer()` runs once at
// game start. There is no localStorage "active content" pointer yet (no content
// editor in this change) — the store always loads the server default.

export const GAME_SLUG = 'dungeon-tactics-solo'

interface ActiveContent {
  cols: number
  rows: number
  // Deserialized board: terrain with destructible structures overlaid.
  cells: Cell[][]
  // Player-placeable tiles as "col,row" keys (reproduces the old spawnZoneTiles()).
  playerSpawnZone: Set<string>
  // Enemy spawner tiles.
  enemySpawners: Array<{ col: number; row: number }>
}

// Rebuild the engine's runtime board from the persisted Map shape: overlay
// `objects` onto the terrain grid — an object *with* `hp` becomes a destructible
// structure cell (HP + kind); one *without* leaves the cell non-structural
// (today's board has no inert objects, and `Cell` has no inert representation) —
// and expose the spawn zones as tile-key sets. Board dimensions come from the
// Map's `size`.
export function deserialize(map: ContentMap): ActiveContent {
  const cells: Cell[][] = map.terrain.map(row =>
    row.map(terrain => ({ terrain, hasStructure: false } as Cell)),
  )
  for (const obj of map.objects) {
    if (obj.hp != null) {
      const base = cells[obj.row][obj.col]
      cells[obj.row][obj.col] = {
        terrain: base.terrain,
        hasStructure: true,
        structureHp: obj.hp,
        structureKind: obj.kind as Cell['structureKind'],
      }
    }
  }
  return {
    cols: map.size.cols,
    rows: map.size.rows,
    cells,
    playerSpawnZone: new Set(map.playerSpawnZone),
    enemySpawners: map.enemySpawnZone.map(key => {
      const [col, row] = key.split(',').map(Number)
      return { col, row }
    }),
  }
}

let active: ActiveContent = deserialize(BUNDLED_MAP.map)
let loadedMapId: string | null = null

// ─── Reads (the single engine seam) ────────────────────────────────────────────

export function gridCols(): number {
  return active.cols
}

export function gridRows(): number {
  return active.rows
}

// A fresh deep copy of the deserialized board, so callers (e.g. `initialState`)
// can mutate freely without touching the canonical content.
export function boardCells(): Cell[][] {
  return active.cells.map(row => row.map(cell => ({ ...cell })))
}

// The set of placeable spawn-zone tile keys ("col,row") — replaces the old
// `spawnZoneTiles()`.
export function playerSpawnZone(): Set<string> {
  return new Set(active.playerSpawnZone)
}

export function enemySpawners(): Array<{ col: number; row: number }> {
  return active.enemySpawners.map(s => ({ ...s }))
}

// The player spawn-zone tiles in a stable order (row, then col). PC initial
// placement is derived from the head of this list (see `npc.ts` `initialState`),
// replacing the removed per-archetype `pcStartTiles`.
export function playerStartTiles(): Array<{ col: number; row: number }> {
  return [...active.playerSpawnZone]
    .map(key => {
      const [col, row] = key.split(',').map(Number)
      return { col, row }
    })
    .sort((a, b) => a.row - b.row || a.col - b.col)
}

export function loadedMap(): string | null {
  return loadedMapId
}

// ─── Server load (no polling — called once at game start) ───────────────────────

// Load the persisted default Map into the store at game start. On any failure
// the store is left as-is (bundled map) so the game stays playable. Returns
// whether a load succeeded.
export async function loadFromServer(): Promise<{ ok: boolean; mapId: string | null }> {
  try {
    const tree = await fetchDefaultContent<ContentTree>(GAME_SLUG)
    active = deserialize(tree.map)
    loadedMapId = tree.map.id
    return { ok: true, mapId: tree.map.id }
  } catch {
    console.warn('[dungeon-tactics] content fetch failed; using bundled map')
    return { ok: false, mapId: null }
  }
}

// Load a specific Map by id into the store — the path used when the player picks
// a map from the start-of-game selection dialog. On failure the store is left
// as-is so the game stays playable. Returns whether the load succeeded.
export async function loadMapById(mapId: string): Promise<{ ok: boolean; mapId: string | null }> {
  try {
    const { map } = await fetchMapWithEncounters<ContentMap, ContentEncounter>(GAME_SLUG, mapId)
    active = deserialize(map)
    loadedMapId = map.id
    return { ok: true, mapId: map.id }
  } catch {
    console.warn('[dungeon-tactics] map fetch failed; using bundled map')
    return { ok: false, mapId: null }
  }
}

// Restore the bundled map (tests / fallback).
export function reset(): void {
  active = deserialize(BUNDLED_MAP.map)
  loadedMapId = null
}

import type { PcType, NpcType, UnitDef } from './types'
import { unitDefs } from './unitDefs'
import { fetchUnitDefs, fetchScenarioUnitDefs } from '../../api'

// The single in-memory source of truth the engine reads unit stats from.
//
// This module replaces the Stage 1 / admin-mode `statOverrides.ts` session layer.
// At game start `loadFromServer()` populates the store from the persisted default
// scenario; if that fetch fails the store keeps the bundled `unitDefs.ts` table so
// the game stays playable offline / on error. The engine (`pc.ts`, `npc.ts`,
// `DungeonTacticsScene.ts`) reads stats only through the getters here — the
// bundled table is imported solely as the fallback seed.
//
// Editing mutates this store directly (instant effect, no reload); the editor
// persists the active scenario's defs in bulk only on explicit Save. There is no
// polling / mid-session re-fetch; `loadFromServer()` is re-run only by the
// explicit "Reload from server" control.
//
// Scenario selection is client-side: the active scenario is whatever the user
// last picked in the editor, remembered per browser in localStorage. The game
// starts on that selection (falling back to the server's default scenario when
// there is no/stale selection). The DB default stays the canonical seed/fallback.

export const GAME_SLUG = 'dungeon-tactics-solo'

// localStorage key for the per-browser active-scenario selection.
const ACTIVE_KEY = 'dungeon-tactics:active-scenario'

function readActiveId(): string | null {
  try { return localStorage.getItem(ACTIVE_KEY) } catch { return null }
}

function writeActiveId(id: string | null): void {
  try {
    if (id) localStorage.setItem(ACTIVE_KEY, id)
    else localStorage.removeItem(ACTIVE_KEY)
  } catch { /* localStorage unavailable — selection just isn't remembered */ }
}

type UnitType = PcType | NpcType

const ALL_UNIT_TYPES: UnitType[] = [
  'melee', 'ranger', 'magic-user', 'rogue', 'short-range', 'long-range',
]

// Engine-valid ranges, mirroring the Zod write schema so a live-applied value can
// never be one the bulk write would later reject.
const HP_MIN = 1
const HP_MAX = 20
const MOVE_MIN = 0
// RANGE_MAX / MOVE_MAX = 22 is the 16×8 board's max Manhattan span
// ((16-1)+(8-1)); nothing can move or reach farther.
const MOVE_MAX = 22
const DAMAGE_MAX = 15
const RANGE_MAX = 22
const MAXRANGE_MIN = 1

let store: Record<UnitType, UnitDef>
let loadedScenarioId: string | null = null

function clone(def: UnitDef): UnitDef {
  return {
    maxHp: def.maxHp,
    movement: { range: def.movement.range },
    attack: {
      damage: def.attack.damage,
      targeting: { ...def.attack.targeting },
      propagation: { ...def.attack.propagation },
    },
  }
}

function seedFromBundled() {
  store = {} as Record<UnitType, UnitDef>
  for (const t of ALL_UNIT_TYPES) store[t] = clone(unitDefs[t])
}

seedFromBundled()

function clampInt(n: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, Math.round(n)))
}

// Clamp every numeric field of a def to the engine-valid ranges (mirroring the
// backend Zod write schema: max HP [1,20], move [0,22], damage [0,15], minRange
// [0,22], maxRange [1,22]). Used at live-apply commit time so the running match
// can never hold a value the bulk write would reject. A defensive
// `maxRange = max(minRange, maxRange)` guarantees no inverted pair enters the
// store from any non-editor path (the editor's mutators reconcile for UX).
export function clampDef(def: UnitDef): UnitDef {
  const t = def.attack.targeting
  const minRange = clampInt(t.minRange, 0, RANGE_MAX)
  const maxRange = Math.max(minRange, clampInt(t.maxRange, MAXRANGE_MIN, RANGE_MAX))
  return {
    maxHp: clampInt(def.maxHp, HP_MIN, HP_MAX),
    movement: { range: clampInt(def.movement.range, MOVE_MIN, MOVE_MAX) },
    attack: {
      damage: clampInt(def.attack.damage, 0, DAMAGE_MAX),
      targeting: {
        ...t,
        minRange,
        maxRange,
      },
      propagation: { ...def.attack.propagation },
    },
  }
}

// Range-pair reconcilers for the editor's Min/Max rng fields. The edited field
// keeps the entered value `v`; the partner is pushed to equal it only when the
// pair would otherwise invert (Max rng < Min rng). The push is direction-
// dependent — only the editing handler knows which field changed — so these are
// per-field, not a symmetric clamp. `clampDef` applies the final bound clamp on
// commit; these only enforce the cross-field ordering for good UX.
//
// Raising Min rng above Max rng raises Max rng to meet it.
export function withMinRange(def: UnitDef, v: number): UnitDef {
  const t = def.attack.targeting
  return {
    ...def,
    attack: { ...def.attack, targeting: { ...t, minRange: v, maxRange: Math.max(v, t.maxRange) } },
  }
}

// Lowering Max rng below Min rng lowers Min rng to meet it.
export function withMaxRange(def: UnitDef, v: number): UnitDef {
  const t = def.attack.targeting
  return {
    ...def,
    attack: { ...def.attack, targeting: { ...t, maxRange: v, minRange: Math.min(v, t.minRange) } },
  }
}

// Structural def equality over the fields the engine reads: maxHp, move range,
// and the full attack block.
function defsEqual(a: UnitDef, b: UnitDef): boolean {
  return (
    a.maxHp === b.maxHp &&
    a.movement.range === b.movement.range &&
    a.attack.damage === b.attack.damage &&
    a.attack.targeting.minRange === b.attack.targeting.minRange &&
    a.attack.targeting.maxRange === b.attack.targeting.maxRange &&
    a.attack.targeting.mode === b.attack.targeting.mode &&
    a.attack.targeting.arc === b.attack.targeting.arc &&
    a.attack.propagation.shape === b.attack.propagation.shape &&
    a.attack.propagation.penetration === b.attack.propagation.penetration
  )
}

// Given an incoming def map, return the set of archetypes whose def differs from
// the store's current value. Drives the granular HP-reconcile + NPC re-plan: the
// editor passes its (clamped) edited map; Reload passes a pre-reload snapshot
// (which, compared against the post-reload store, yields exactly the restored
// archetypes).
export function diffDefs(incoming: Partial<Record<UnitType, UnitDef>>): Set<UnitType> {
  const changed = new Set<UnitType>()
  for (const t of ALL_UNIT_TYPES) {
    const next = incoming[t]
    if (next && !defsEqual(getDef(t), next)) changed.add(t)
  }
  return changed
}

// ─── Reads (the single engine seam) ────────────────────────────────────────────

export function getDef(unitType: UnitType): UnitDef {
  return store[unitType] ?? unitDefs[unitType]
}

export function getMaxHp(unitType: UnitType): number {
  return getDef(unitType).maxHp
}

export function getMoveRange(unitType: UnitType): number {
  return getDef(unitType).movement.range
}

// A defensive copy of the full table for editor seeding.
export function getAllDefs(): Record<UnitType, UnitDef> {
  const out = {} as Record<UnitType, UnitDef>
  for (const t of ALL_UNIT_TYPES) out[t] = clone(getDef(t))
  return out
}

export function loadedScenario(): string | null {
  return loadedScenarioId
}

// ─── Write-through edits (immediate; persistence is the caller's job) ───────────

// Replace an archetype's full def in the store (used by the editor panel for the
// currently-loaded scenario so edits apply without a reload).
export function setDef(unitType: UnitType, def: UnitDef): void {
  store[unitType] = clone(def)
}

export function setMaxHp(unitType: UnitType, n: number): number {
  const v = clampInt(n, HP_MIN, HP_MAX)
  store[unitType] = { ...getDef(unitType), maxHp: v }
  return v
}

export function setMoveRange(unitType: UnitType, n: number): number {
  const v = clampInt(n, MOVE_MIN, MOVE_MAX)
  const def = getDef(unitType)
  store[unitType] = { ...def, movement: { ...def.movement, range: v } }
  return v
}

// ─── Server load / reload (no polling — called once at start, then on demand) ───

// Replace the store from a fetched def map: start from bundled defaults, then
// overlay every archetype the server knows so a partial response can never leave
// an archetype undefined.
function applyLoaded(loaded: Record<string, UnitDef>): void {
  seedFromBundled()
  for (const t of ALL_UNIT_TYPES) {
    if (loaded[t]) store[t] = clone(loaded[t])
  }
}

// Load the active scenario into the store at game start (and on "Reload from
// server"). Prefers the per-browser selection (localStorage); falls back to the
// server's default scenario when there is no selection or it is stale/missing.
// On total failure the store is left as-is (bundled defaults) so the game stays
// playable. Returns whether a load succeeded and which scenario is now active.
export async function loadFromServer(): Promise<{ ok: boolean; scenarioId: string | null }> {
  const preferred = readActiveId()
  if (preferred) {
    try {
      applyLoaded(await fetchScenarioUnitDefs<UnitDef>(GAME_SLUG, preferred))
      loadedScenarioId = preferred
      return { ok: true, scenarioId: preferred }
    } catch {
      // Stale/deleted selection — forget it and fall back to the default.
      writeActiveId(null)
    }
  }
  try {
    const { scenarioId, unitDefs: loaded } = await fetchUnitDefs<UnitDef>(GAME_SLUG)
    applyLoaded(loaded)
    loadedScenarioId = scenarioId
    return { ok: true, scenarioId }
  } catch {
    console.warn('[dungeon-tactics] unit-def fetch failed; using bundled defaults')
    return { ok: false, scenarioId: null }
  }
}

// Switch the active scenario: fetch its defs, swap the store, and remember the
// selection (per browser) so the game starts on it next time. The caller is
// responsible for any board redraw / HP reconciliation. Returns success.
export async function loadScenario(scenarioId: string): Promise<{ ok: boolean }> {
  try {
    applyLoaded(await fetchScenarioUnitDefs<UnitDef>(GAME_SLUG, scenarioId))
    loadedScenarioId = scenarioId
    writeActiveId(scenarioId)
    return { ok: true }
  } catch {
    return { ok: false }
  }
}

// Restore every archetype to its bundled default (tests / fallback).
export function reset(): void {
  seedFromBundled()
  loadedScenarioId = null
}

import * as Phaser from 'phaser'
import type { Cell } from './types'

// Shared board rendering for the play scene (`DungeonTacticsScene`) and the studio
// editor scene (`EditorScene`). Both draw terrain + structures the same way through
// `drawBoard`, so authored boards look exactly like played boards — and both will
// inherit the sprite tileset together when `dungeon-tactics-sprite-rendering` lands
// (this file becomes its single upgrade point). Editor-only overlays (zone tints,
// grid lines, hover/brush cursor) live in the editor scene, on top of this.

export const TILE_SIZE = 80

export const TERRAIN_COLORS: Record<string, number> = {
  plains: 0xd4a853,
  forest: 0x2d6a2f,
  water: 0x2b72b5,
  stone: 0x7d7d7d,
}

const STRUCTURE_COLOR = 0x8b5a2b
const TOWER_COLOR = 0xd4a000

export function tileCX(col: number) { return col * TILE_SIZE + TILE_SIZE / 2 }
export function tileCY(row: number) { return row * TILE_SIZE + TILE_SIZE / 2 }

// Draw terrain rects (with grid stroke) and any structures (power-center/tower
// body, tower cross + immunity ring, HP pips) for the whole grid into `gfx`. The
// caller clears/owns `gfx`. `towerImmune` draws the tower's blue protection ring.
export function drawBoard(
  gfx: Phaser.GameObjects.Graphics,
  cells: Cell[][],
  opts: { towerImmune: boolean },
) {
  const rows = cells.length
  for (let row = 0; row < rows; row++) {
    const cols = cells[row].length
    for (let col = 0; col < cols; col++) {
      const cell = cells[row][col]
      const color = TERRAIN_COLORS[cell.terrain] ?? 0x444444
      gfx.fillStyle(color)
      gfx.fillRect(col * TILE_SIZE, row * TILE_SIZE, TILE_SIZE, TILE_SIZE)
      gfx.lineStyle(1, 0x000000, 0.4)
      gfx.strokeRect(col * TILE_SIZE, row * TILE_SIZE, TILE_SIZE, TILE_SIZE)

      if (cell.hasStructure) {
        const isTower = cell.structureKind === 'tower'
        const m = TILE_SIZE * (isTower ? 0.12 : 0.18)
        gfx.fillStyle(isTower ? TOWER_COLOR : STRUCTURE_COLOR)
        gfx.fillRect(col * TILE_SIZE + m, row * TILE_SIZE + m, TILE_SIZE - 2 * m, TILE_SIZE - 2 * m)

        if (isTower) {
          const cx = col * TILE_SIZE + TILE_SIZE / 2
          const cy = row * TILE_SIZE + TILE_SIZE / 2
          const arm = TILE_SIZE * 0.22
          gfx.lineStyle(4, 0xffffff, 0.7)
          gfx.beginPath()
          gfx.moveTo(cx - arm, cy); gfx.lineTo(cx + arm, cy)
          gfx.moveTo(cx, cy - arm); gfx.lineTo(cx, cy + arm)
          gfx.strokePath()
          // Blue immunity ring when protected
          if (opts.towerImmune) {
            gfx.lineStyle(3, 0x44aaff, 0.85)
            gfx.strokeRect(col * TILE_SIZE + 2, row * TILE_SIZE + 2, TILE_SIZE - 4, TILE_SIZE - 4)
          }
        }

        // HP pips on the left edge, stacked bottom-to-top
        const hp = cell.structureHp ?? 3
        const maxHp = isTower ? 5 : 3
        const pipW = 6; const pipH = isTower ? 7 : 10; const pipGap = 2
        for (let i = 0; i < maxHp; i++) {
          const pipX = col * TILE_SIZE + 3
          const pipY = (row + 1) * TILE_SIZE - 4 - (i + 1) * pipH - i * pipGap
          if (i < hp) {
            gfx.fillStyle(isTower ? 0xffdd44 : 0x22cc44)
            gfx.fillRect(pipX, pipY, pipW, pipH)
          }
          gfx.lineStyle(1, 0x333333, 1)
          gfx.strokeRect(pipX, pipY, pipW, pipH)
